import static org.assertj.core.api.Assertions.assertThat;

import com.mycompany.model.invoice.Invoice;
import com.mycompany.service.InvoiceManagementService;

public class CreateInvoiceScenario extends Scenario {

    @Dependencies
    public SpringBootApplication app;

    private InvoiceManagementService invoiceManagementService;

    @BeforeScenario
    public void setup() {
        this.invoiceManagementService = new InvoiceManagementService(app.getBean(OracleEbsClient.class));
    }

    @Then("a new invoice record is created in the oracle ebs system")
    public void thenARecordIsCreatedInOracleEbs() {
        Invoice invoice =
