Sie können die glTF-Dateien extrahieren, indem Sie entweder das folgende JavaScript-Code exempleieren, oder ein externes Tool wie glTF Viewer oder glTF Studio benutzen:

1. JavaScript-Code:

```javascript
// Benutze das glTF.js-Modul, um GLB-Dateien in glTF-Dateien umzuwandeln.
const gltf = await import('https://unpkg.com/@tensorflow/tfjs@3.1.0/dist/imap.min.js');

// Definiere eine async-Funktion, um die glTF-Dateien aus dem GLB-Objekt zu extrahieren
async function extractAnimations(glbBlob) {
  const glbArrayBuffer = new ArrayBuffer(glbBlob.length);
  const glbArrayView = new Uint8Array(glbArrayBuffer);
  glbArrayView.set(new Uint8Array(glbBlob));

  const gltfBuffer = await gltf.binary.parse(glbArrayBuffer);

  // Extrahiere die Animationen aus der glTF-Datei
  const animations = gltfBuffer.animations;

  return animations;
}

// Aufruf der Funktion mit dem GLB-Objekt als Argument
const glbBlob = fetch('pfad_zum_glb_objekt')
  .then(response => response.arrayBuffer())
  .then(buffer => extractAnimations(buffer));

// Extracts the animations from the glTF data and returns them
